                println!("{}", base);
                return;
            } else { eprintln!("error: patch `base` does not exist"); std::process::exit(1); }
        }
    }
    if rev.ends_with('^') {
        let patch_name = rev.trim_end_matches('^');
        let (b, p) = if patch_name.contains(':') {
            let parts: Vec<&str> = patch_name.splitn(2, ':').collect();
            (parts[0].to_string(), parts[1].to_string())
        } else { (branch.clone(), patch_name.to_string()) };
        let target_stack = if b == branch { stack.clone() } else {
            let (s2, _, _) = read_stack_json(&b).unwrap();
            s2
        };
        if let Some(meta) = target_stack.patches.get(&p) {
            let oid = meta.oid.clone();
            let out = run_git_output(&["log", "-1", "--pretty=%P", &oid]).unwrap();
            let parent = out.trim().split_whitespace().next().unwrap_or("").to_string();
            println!("{}", parent);
            return;
        } else {
            match run_git_output(&["rev-parse", &rev]) {
                Ok(h) => { println!("{}", h.trim()); return; }
                Err(_) => { eprintln!("error: patch `{}` does not exist", p); std::process::exit(1); }
            }
        }
    }
    if rev.contains(':') {
        let parts: Vec<&str> = rev.splitn(2, ':').collect();
        let b = parts[0];
        let p = parts[1];
        if p == "{base}" {
            if stack_ref_exists(b) {
                let (s, _, _) = read_stack_json(b).unwrap();
                let base = get_base_commit(&s, b).unwrap();
                println!("{}", base);
                return;
            } else { eprintln!("error: patch `base` does not exist"); std::process::exit(1); }
        } else {
            if stack_ref_exists(b) {
                let (s, _, _) = read_stack_json(b).unwrap();
                if let Some(meta) = s.patches.get(p) { println!("{}", meta.oid); return; }
                else { eprintln!("error: patch `{}` does not exist", p); std::process::exit(1); }
            } else { eprintln!("error: patch `{}` does not exist", p); std::process::exit(1); }
        }
    }
    if let Some(meta) = stack.patches.get(&rev) { println!("{}", meta.oid); return; }
    match run_git_output(&["rev-parse", &rev]) {
        Ok(h) => { println!("{}", h.trim()); }
        Err(_) => { eprintln!("error: patch `{}` does not exist", rev); std::process::exit(1); }
    }
}
fn do_name(rev_opt: Option<String>, branch_opt: Option<String>, showbranch: bool) {
    let branch = branch_opt.unwrap_or_else(|| get_current_branch().unwrap_or_else(|e| { eprintln!("error: {}", e); std::process::exit(1); }));
    if !stack_ref_exists(&branch) { eprintln!("error: patch `base` does not exist"); std::process::exit(1); }
    let (stack, _, _) = read_stack_json(&branch).unwrap();
    let rev = rev_opt.unwrap_or_else(|| "".to_string());
    let target_oid = if rev.is_empty() {
        if let Some(top) = stack.applied.last() { stack.patches.get(top).unwrap().oid.clone() }
        else { eprintln!("error: no patches applied"); std::process::exit(1); }
    } else {
        if let Some(meta) = stack.patches.get(&rev) { meta.oid.clone() }
        else {
            match run_git_output(&["rev-parse", &rev]) {
                Ok(h) => h.trim().to_string(),
                Err(_) => { eprintln!("error: patch `{}` does not exist", rev); std::process::exit(1); }
            }
        }
    };
    for (name, meta) in &stack.patches {
        if meta.oid == target_oid {
            if showbranch { println!("{}:{}", branch, name); } else { println!("{}", name); }
            return;
        }
    }
    eprintln!("error: patch `{}` does not exist", rev);
    std::process::exit(1);
}
fn do_diff(path: Vec<String>, range: Option<String>, stat: bool, diff_opt: Vec<String>) {
    if let Some(r) = range {
        if r.contains("..") {
            let parts: Vec<&str> = r.split("..").collect();
            let rev1 = parts[0];
            let rev2 = if parts.len()>1 { parts[1] } else { "" };
            let mut args = vec!["diff".to_string()];
            if stat { args.push("--stat".to_string()); }
            for opt in &diff_opt { args.push(opt.clone()); }
            let rev1_resolved = resolve_rev_for_diff(rev1).unwrap_or_else(|| rev1.to_string());
            if rev2.is_empty() {
                args.push(rev1_resolved);
                if !path.is_empty() { args.push("--".to_string()); for p in &path { args.push(p.clone()); } }
            } else {
                let rev2_resolved = resolve_rev_for_diff(rev2).unwrap_or_else(|| rev2.to_string());
                args.push(rev1_resolved);
                args.push(rev2_resolved);
                if !path.is_empty() { args.push("--".to_string()); for p in &path { args.push(p.clone()); } }
            }
            let _ = Command::new("git").args(&args).status();
        } else {
            let rev_resolved = resolve_rev_for_diff(&r).unwrap_or_else(|| r.clone());
            let mut args = vec!["diff".to_string()];
            if stat { args.push("--stat".to_string()); }
            for opt in &diff_opt { args.push(opt.clone()); }
            args.push(rev_resolved);
            if !path.is_empty() { args.push("--".to_string()); for p in &path { args.push(p.clone()); } }
            let _ = Command::new("git").args(&args).status();
        }
    } else {
        let mut args = vec!["diff".to_string()];
        if stat { args.push("--stat".to_string()); }
        for opt in &diff_opt { args.push(opt.clone()); }
        args.push("HEAD".to_string());
        if !path.is_empty() { args.push("--".to_string()); for p in &path { args.push(p.clone()); } }
        let _ = Command::new("git").args(&args).status();
    }
}
fn resolve_rev_for_diff(rev: &str) -> Option<String> {
    if rev.is_empty() { return None; }
    let branch = get_current_branch().ok()?;
    if !stack_ref_exists(&branch) { return None; }
    let (stack, _, _) = read_stack_json(&branch).ok()?;
    if let Some(meta) = stack.patches.get(rev) { return Some(meta.oid.clone()); }
    if rev == "{base}" { return get_base_commit(&stack, &branch).ok(); }
    if let Ok(out) = run_git_output(&["rev-parse", rev]) { return Some(out.trim().to_string()); }
    None
}
fn do_files(revision: Option<String>, stat: bool, branch_opt: Option<String>) {
    let branch = branch_opt.unwrap_or_else(|| get_current_branch().unwrap_or_else(|e| { eprintln!("error: {}", e); std::process::exit(1); }));
    if !stack_ref_exists(&branch) { eprintln!("error: no patches applied"); std::process::exit(1); }
    let (stack, _, _) = read_stack_json(&branch).unwrap();
    let target_rev = revision.unwrap_or_else(|| {
        if let Some(top) = stack.applied.last() { stack.patches.get(top).unwrap().oid.clone() }
        else { eprintln!("error: no patches applied"); std::process::exit(1); }
    });
    let commit_oid = if let Some(meta) = stack.patches.get(&target_rev) { meta.oid.clone() }
    else {
        match run_git_output(&["rev-parse", &target_rev]) {
            Ok(h) => h.trim().to_string(),
            Err(_) => { eprintln!("error: patch `{}` does not exist", target_rev); std::process::exit(1); }
        }
    };
    let parent = run_git_output(&["log", "-1", "--pretty=%P", &commit_oid]).unwrap_or_default().trim().split_whitespace().next().unwrap_or("").to_string();
    if parent.is_empty() { return; }
    let args = if stat { vec!["diff", "--name-status", &parent, &commit_oid] } else { vec!["diff", "--name-only", &parent, &commit_oid] };
    let _ = Command::new("git").args(&args).status();
}
fn do_show(patch_or_rev: Vec<String>, patch_opt: Vec<String>, branch_opt: Option<String>, stat: bool, diff_opt: Vec<String>, applied: bool, unapplied: bool, hidden: bool) {
    let branch = branch_opt.unwrap_or_else(|| get_current_branch().unwrap_or_else(|e| { eprintln!("error: {}", e); std::process::exit(1); }));
    if !stack_ref_exists(&branch) { eprintln!("error: no patches applied"); std::process::exit(1); }
    let (stack, _, _) = read_stack_json(&branch).unwrap();
    let mut revs: Vec<String> = Vec::new();
    if !patch_or_rev.is_empty() { revs.extend(patch_or_rev); }
    if !patch_opt.is_empty() { revs.extend(patch_opt); }
    if revs.is_empty() {
        if applied { for name in &stack.applied { revs.push(name.clone()); } }
        else if unapplied { for name in &stack.unapplied { revs.push(name.clone()); } }
        else if hidden { for name in &stack.hidden { revs.push(name.clone()); } }
        else { if let Some(top) = stack.applied.last() { revs.push(top.clone()); } else { eprintln!("error: no patches applied"); std::process::exit(1); } }
    }
    let mut expanded: Vec<String> = Vec::new();
    for r in revs {
        if r.contains("..") {
            let parts: Vec<&str> = r.split("..").collect();
            let begin = parts[0];
            let end = parts[1];
            let all_patches: Vec<String> = { let mut v = stack.applied.clone(); v.extend(stack.unapplied.clone()); v.extend(stack.hidden.clone()); v };
            let begin_idx = if begin.is_empty() { 0 } else { all_patches.iter().position(|x| x==begin).unwrap_or(0) };
            let end_idx = if end.is_empty() { all_patches.len()-1 } else { all_patches.iter().position(|x| x==end).unwrap_or(all_patches.len()-1) };
            for idx in begin_idx..=end_idx { expanded.push(all_patches[idx].clone()); }
        } else { expanded.push(r); }
    }
    for rev in expanded {
        let commit_oid = if let Some(meta) = stack.patches.get(&rev) { meta.oid.clone() }
        else {
            match run_git_output(&["rev-parse", &rev]) {
                Ok(h) => h.trim().to_string(),
                Err(_) => { eprintln!("error: patch `{}` does not exist", rev); continue; }
            }
        };
        let mut args = vec!["show".to_string()];
        if stat { args.push("--stat".to_string()); }
        for opt in &diff_opt { args.push(opt.clone()); }
        args.push(commit_oid);
        let _ = Command::new("git").args(&args).status();
    }
}
fn do_log(_patch_filter: Vec<String>, branch_opt: Option<String>, _diff: bool, number: Option<usize>, _full: bool, _graphical: bool, clear: bool) {
    let branch = branch_opt.unwrap_or_else(|| get_current_branch().unwrap_or_else(|e| { eprintln!("error: {}", e); std::process::exit(1); }));
    if !stack_ref_exists(&branch) { return; }
    let (stack, tip, _) = read_stack_json(&branch).unwrap();
    if clear { return; }
    let mut current = Some(tip.clone());
    let mut count = 0;
    while let Some(commit) = current {
        if let Some(n) = number { if count >= n { break; } }
        let out = run_git_output(&["log", "-1", "--pretty=format:%h   %ad   %s", "--date=rfc", &commit]).unwrap_or_default();
        println!("{}", out);
        let parents_out = run_git_output(&["log", "-1", "--pretty=%P", &commit]).unwrap_or_default();
        let parents: Vec<String> = parents_out.trim().split_whitespace().map(|s| s.to_string()).collect();
        if parents.is_empty() { break; }
        let meta_commit = &parents[0];
        let ls = run_git_output(&["ls-tree", meta_commit]).unwrap_or_default();
        let mut blob_oid = None;
        for line in ls.lines() {
            if line.contains("stack.json") {
                let parts: Vec<&str> = line.split_whitespace().collect();
                if parts.len()>=3 { blob_oid = Some(parts[2].to_string()); }
            }
        }
        if let Some(oid) = blob_oid {
            let content = run_git_output(&["cat-file", "-p", &oid]).unwrap_or_default();
            if let Ok(sj) = serde_json::from_str::<StackJson>(&content) {
                current = sj.prev.clone();
            } else { current = None; }
        } else { current = None; }
        count+=1;
    }
}
fn do_branch(branch_arg: Option<String>, list: bool, create: Option<String>, clone_opt: Option<Option<String>>, delete: Option<Option<String>>, cleanup: Option<Option<String>>, merge: bool, force: bool, extra: Vec<String>) {
    if list {
        let out = run_git_output(&["branch", "--list"]).unwrap_or_default();
        let _current = get_current_branch().unwrap_or_default();
        for line in out.lines() {
            let clean = line.trim().trim_start_matches("* ").trim();
            let is_current = line.contains("*");
            let has_stack = stack_ref_exists(clean);
            let marker = if has_stack { "s" } else { " " };
            if is_current { println!("> {} \t{}  |", marker, clean); } else { println!("  {} \t{}  |", marker, clean); }
        }
        return;
    }
    if let Some(new_branch) = create {
        let committish = if !extra.is_empty() { extra[0].clone() } else { "HEAD".to_string() };
        let status = Command::new("git").args(&["branch", &new_branch, &committish]).status().unwrap();
        if !status.success() { std::process::exit(1); }
        let _ = Command::new("git").args(&["checkout", &new_branch]).status();
        if !stack_ref_exists(&new_branch) { do_init(Some(new_branch.clone())); }
        return;
    }
    if let Some(clone_val) = clone_opt {
        let new_branch_name = match clone_val {
            Some(Some(name)) => name,
            _ => {
                let cur = get_current_branch().unwrap();
                format!("{}-clone-{}", cur, chrono::Utc::now().timestamp())
            }
        };
        let cur_branch = get_current_branch().unwrap();
        let cur_head = get_current_head_commit().unwrap();
        let _ = Command::new("git").args(&["branch", &new_branch_name, &cur_head]).status();
        if stack_ref_exists(&cur_branch) {
            let tip = get_stack_tip_commit(&cur_branch).unwrap();
            let new_ref = format!("refs/stacks/{}", new_branch_name);
            let _ = Command::new("git").args(&["update-ref", &new_ref, &tip]).status();
            let out = run_git_output(&["show-ref"]).unwrap_or_default();
            for line in out.lines() {
                if line.contains(&format!("refs/patches/{}/", cur_branch)) {
                    let parts: Vec<&str> = line.split_whitespace().collect();
                    if parts.len()==2 {
                        let hash = parts[0];
                        let refname = parts[1];
                        let new_refname = refname.replace(&format!("refs/patches/{}/", cur_branch), &format!("refs/patches/{}/", new_branch_name));
                        let _ = Command::new("git").args(&["update-ref", &new_refname, hash]).status();
                    }
                }
            }
        }
        let _ = Command::new("git").args(&["checkout", &new_branch_name]).status();
        return;
    }
    if let Some(del) = delete {
        let branch_to_del = match del {
            Some(name) => name,
            None => { if let Some(b) = branch_arg.clone() { b } else { eprintln!("error: branch name required"); std::process::exit(1); } }
        };
        let mut args = vec!["branch".to_string(), "-D".to_string()];
        if !force { args = vec!["branch".to_string(), "-d".to_string()]; }
        args.push(branch_to_del.clone());
        let status = Command::new("git").args(&args).status().unwrap();
        if !status.success() { std::process::exit(1); }
        let refname = format!("refs/stacks/{}", branch_to_del);
        let _ = Command::new("git").args(&["update-ref", "-d", &refname]).status();
        return;
    }
    if let Some(_) = cleanup {
        let branch_to_clean = cleanup.unwrap_or_else(|| Some(get_current_branch().unwrap())).unwrap_or_else(|| get_current_branch().unwrap());
        let refname = format!("refs/stacks/{}", branch_to_clean);
        let _ = Command::new("git").args(&["update-ref", "-d", &refname]).status();
        return;
    }
    if let Some(br) = branch_arg {
        if merge {
            let status = Command::new("git").args(&["checkout", &br]).status().unwrap();
            if !status.success() { std::process::exit(1); }
        } else {
            let status = Command::new("git").args(&["checkout", &br]).status().unwrap();
            if !status.success() { std::process::exit(1); }
        }
        println!("{}", br);
        return;
    }
    let cur = get_current_branch().unwrap();
    println!("{}", cur);
}
fn do_export(patch: Vec<String>, branch_opt: Option<String>, dir_opt: Option<String>, patch_suffix: bool, extension: Option<String>, numbered: bool, stdout_flag: bool, _diff_opt: Vec<String>) {
    let branch = branch_opt.unwrap_or_else(|| get_current_branch().unwrap_or_else(|e| { eprintln!("error: {}", e); std::process::exit(1); }));
    if !stack_ref_exists(&branch) { return; }
    let (stack, _, _) = read_stack_json(&branch).unwrap();
    let patches_to_export: Vec<String> = if patch.is_empty() {
        let mut v = stack.applied.clone();
        v.extend(stack.unapplied.clone());
        v
    } else {
        let mut expanded = Vec::new();
        for p in patch {
            if p.contains("..") {
                let parts: Vec<&str> = p.split("..").collect();
                let begin = parts[0];
                let end = parts[1];
                let all: Vec<String> = { let mut v = stack.applied.clone(); v.extend(stack.unapplied.clone()); v };
                let b_idx = all.iter().position(|x| x==begin).unwrap_or(0);
                let e_idx = all.iter().position(|x| x==end).unwrap_or(all.len()-1);
                for idx in b_idx..=e_idx { expanded.push(all[idx].clone()); }
            } else { expanded.push(p); }
        }
        expanded
    };
    let out_dir = dir_opt.unwrap_or_else(|| "patches-".to_string() + &branch);
    if !stdout_flag { let _ = fs::create_dir_all(&out_dir); }
    if !stdout_flag {
        let series_path = Path::new(&out_dir).join("series");
        let mut series_content = String::new();
        for (i, pname) in patches_to_export.iter().enumerate() {
            let filename = if numbered { format!("{:02}-{}", i+1, pname) } else { pname.clone() };
            let suffix = if patch_suffix { ".patch" } else if let Some(ext) = &extension { &format!(".{}", ext) } else { "" };
            series_content.push_str(&format!("{}{}\n", filename, suffix));
        }
        let _ = fs::write(series_path, series_content);
    }
    for (i, pname) in patches_to_export.iter().enumerate() {
        let oid = match stack.patches.get(pname) { Some(m) => m.oid.clone(), None => continue, };
        let content = run_git_output(&["show", &oid]).unwrap_or_default();
        if stdout_flag {
            println!("{}", content);
        } else {
            let filename = if numbered { format!("{:02}-{}", i+1, pname) } else { pname.clone() };
            let suffix = if patch_suffix { ".patch".to_string() } else if let Some(ext) = &extension { format!(".{}", ext) } else { "".to_string() };
            let filepath = Path::new(&out_dir).join(format!("{}{}", filename, suffix));
            let _ = fs::write(filepath, content);
        }
    }
}
fn do_patches(path: Vec<String>, branch_opt: Option<String>, diff_flag: bool, _diff_opt: Vec<String>) {
    let branch = branch_opt.unwrap_or_else(|| get_current_branch().unwrap_or_else(|e| { eprintln!("error: {}", e); std::process::exit(1); }));
    if !stack_ref_exists(&branch) { return; }
    let (stack, _, _) = read_stack_json(&branch).unwrap();
    let target_paths: Vec<String> = if path.is_empty() {
        let out = run_git_output(&["diff", "--name-only", "HEAD"]).unwrap_or_default();
        out.lines().map(|s| s.to_string()).collect()
    } else { path.clone() };
    for pname in &stack.applied {
        let oid = stack.patches.get(pname).unwrap().oid.clone();
        let parent = run_git_output(&["log", "-1", "--pretty=%P", &oid]).unwrap_or_default().trim().split_whitespace().next().unwrap_or("").to_string();
        if parent.is_empty() { continue; }
        let out = run_git_output(&["diff", "--name-only", &parent, &oid]).unwrap_or_default();
        let modified_files: Vec<String> = out.lines().map(|s| s.to_string()).collect();
        if target_paths.iter().any(|tp| modified_files.contains(tp)) {
            if diff_flag { let _ = Command::new("git").args(&["show", &oid]).status(); }
            else { println!("{}", pname); }
        }
    }
}
