shopt -s extglob

__stg ()
{
    stg ${__C_args:+"${__C_args[@]}"} "$@" 2>/dev/null
}

"#;
            if let Some(out_path) = output { let _ = fs::write(out_path, script); } else { print!("{}", script); }
        }
        Some(CompletionCommands::Fish { output, .. }) => {
