        target_oid = stack["patches"][target_patch_name]["oid"]
        out_parent = run_git_output(["log","-1","--pretty=%P", target_oid], cwd=cwd).strip()
        parent_of_target = out_parent.split()[0] if out_parent else get_base_commit(stack, branch, cwd=cwd)
        parent_tree = get_tree_of_commit(parent_of_target, cwd=cwd)
    except Exception as e:
        print(f"error: {e}", file=sys.stderr)
        sys.exit(1)
    if index_flag:
        try:
            new_tree = run_git_output(["write-tree"], cwd=cwd).strip()
        except Exception as e:
            print(f"error: {e}", file=sys.stderr)
            sys.exit(1)
    else:
        if not path_args:
            subprocess.run(["git","add","--all"], cwd=cwd)
        else:
            subprocess.run(["git","add","--"]+path_args, cwd=cwd)
        try:
            new_tree = run_git_output(["write-tree"], cwd=cwd).strip()
        except Exception as e:
            print(f"error: {e}", file=sys.stderr)
            sys.exit(1)
        subprocess.run(["git","reset"], cwd=cwd)
    if message_opt:
        new_message = message_opt
    elif file_opt:
        if file_opt == "-":
            new_message = sys.stdin.read()
        else:
            try:
                with open(file_opt) as f:
                    new_message = f.read()
            except Exception as e:
                print(f"error: {e}", file=sys.stderr)
                sys.exit(1)
    else:
        try:
            new_message = get_commit_message(target_oid, cwd=cwd)
        except:
            new_message = "refresh"
    try:
        new_patch_commit = git_commit_tree(new_tree, [parent_of_target], new_message, cwd=cwd)
    except Exception as e:
        print(f"error: {e}", file=sys.stderr)
        sys.exit(1)
    # Rebase patches above if any
    pos = stack["applied"].index(target_patch_name)
    new_head = new_patch_commit
    new_patches_map = dict(stack["patches"])
    new_patches_map[target_patch_name]={"oid":new_patch_commit}
    if pos+1 < len(stack["applied"]):
        current_head = new_head
        for idx in range(pos+1, len(stack["applied"])):
            pname = stack["applied"][idx]
            old_oid = stack["patches"][pname]["oid"]
            temp_branch = f"stg-rebase-temp-{idx}"
            subprocess.run(["git","checkout","-b",temp_branch, current_head], cwd=cwd, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            ret = subprocess.run(["git","cherry-pick","--no-commit", old_oid], cwd=cwd).returncode
            if ret!=0:
                subprocess.run(["git","add","--all"], cwd=cwd)
            try:
                new_tree_cherry = run_git_output(["write-tree"], cwd=cwd).strip()
            except:
                new_tree_cherry = get_tree_of_commit(current_head, cwd=cwd)
            try:
                msg = get_commit_message(old_oid, cwd=cwd)
            except:
                msg = pname
            try:
                new_commit = git_commit_tree(new_tree_cherry, [current_head], msg, cwd=cwd)
            except Exception as e:
                print(f"error: {e}", file=sys.stderr)
                sys.exit(1)
            subprocess.run(["git","checkout", branch], cwd=cwd, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            subprocess.run(["git","branch","-D", temp_branch], cwd=cwd, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            current_head = new_commit
            new_patches_map[pname]={"oid":new_commit}
        new_head = current_head
    # update branch
    branch_ref = f"refs/heads/{branch}"
    try:
        run_git_output(["update-ref", branch_ref, new_head], cwd=cwd)
        subprocess.run(["git","reset","--hard", new_head], cwd=cwd, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    except Exception as e:
        print(f"error: {e}", file=sys.stderr)
        sys.exit(1)
    # rebuild patches blobs
    existing_blobs = {}
    try:
        out_ls = run_git_output(["ls-tree", old_meta], cwd=cwd)
        old_patches_tree_oid = None
        for line in out_ls.splitlines():
            if "\\tpatches" in line:
                before_tab, after_tab = line.split("\\t",1)
                if after_tab=="patches":
                    old_patches_tree_oid = before_tab.split()[2]
        if old_patches_tree_oid and old_patches_tree_oid != "4b825dc642cb6eb9a060e54bf8d69288fbee4904":
            out = run_git_output(["ls-tree", old_patches_tree_oid], cwd=cwd)
            for l in out.splitlines():
                if "\\t" in l:
                    meta, name = l.split("\\t",1)
                    oid = meta.split()[2]
                    existing_blobs[name]=oid
    except:
        pass
    try:
        author, date = get_commit_author(new_patch_commit, cwd=cwd)
    except:
        author="Test <test@test.com>"
        date="2026-09-08 00:00:00 +0000"
    try:
        patch_msg = get_commit_message(new_patch_commit, cwd=cwd)
    except:
        patch_msg = new_message
    try:
        new_patch_blob = create_patch_blob(parent_tree, new_tree, author, date, patch_msg, cwd=cwd)
    except Exception as e:
        print(f"error: {e}", file=sys.stderr)
        sys.exit(1)
    existing_blobs[target_patch_name]=new_patch_blob
    if pos+1 < len(stack["applied"]):
        for idx in range(pos+1, len(stack["applied"])):
            pname = stack["applied"][idx]
            new_oid = new_patches_map[pname]["oid"]
            parent_oid = new_patch_commit if idx==pos+1 else new_patches_map[stack["applied"][idx-1]]["oid"]
            try:
                bottom_tree = get_tree_of_commit(parent_oid, cwd=cwd)
                top_tree = get_tree_of_commit(new_oid, cwd=cwd)
                auth, d = get_commit_author(new_oid, cwd=cwd)
                msg = get_commit_message(new_oid, cwd=cwd)
                blob = create_patch_blob(bottom_tree, top_tree, auth, d, msg, cwd=cwd)
                existing_blobs[pname]=blob
            except Exception as e:
                print(f"error: {e}", file=sys.stderr)
                sys.exit(1)
    try:
        new_patches_tree = build_patches_tree(existing_blobs, cwd=cwd)
        new_stack = {
            "version":5,
            "prev":old_tip,
            "head":new_head,
            "applied": stack["applied"],
            "unapplied": stack["unapplied"],
            "hidden": stack["hidden"],
            "patches": new_patches_map
        }
        new_stack_blob = write_stack_json(new_stack, cwd=cwd)
        new_meta_tree = create_tree_with_stack_and_patches(new_stack_blob, new_patches_tree, cwd=cwd)
        new_meta_commit = git_commit_tree(new_meta_tree, [old_meta], f"refresh {target_patch_name}", cwd=cwd)
        new_stacks_commit = git_commit_tree(new_meta_tree, [new_meta_commit, new_head, old_tip], f"refresh {target_patch_name}", cwd=cwd)
        refname = f"refs/stacks/{branch}"
        run_git_output(["update-ref", refname, new_stacks_commit], cwd=cwd)
        patch_ref = f"refs/patches/{branch}/{target_patch_name}"
        run_git_output(["update-ref", patch_ref, new_patch_commit], cwd=cwd)
        if pos+1 < len(stack["applied"]):
            for idx in range(pos+1, len(stack["applied"])):
                pname = stack["applied"][idx]
                new_oid = new_stack["patches"][pname]["oid"]
                pr = f"refs/patches/{branch}/{pname}"
                run_git_output(["update-ref", pr, new_oid], cwd=cwd)
    except Exception as e:
        print(f"error: {e}", file=sys.stderr)
        sys.exit(1)

def do_pop(patch_args=None, all_flag=False, number=None, spill=False, keep=False, cwd=None):
    if patch_args is None:
        patch_args=[]
    branch = get_current_branch(cwd=cwd)
    if not stack_ref_exists(branch, cwd=cwd):
        print("error: no patches applied", file=sys.stderr)
        sys.exit(1)
    try:
        stack, old_tip, old_meta = read_stack_json(branch, cwd=cwd)
    except Exception as e:
        print(f"error: {e}", file=sys.stderr)
        sys.exit(1)
    if not stack.get("applied"):
        print("error: no patches applied", file=sys.stderr)
        sys.exit(1)
    has_unstaged = subprocess.run(["git","diff-files","--quiet"], cwd=cwd).returncode !=0
    has_staged = subprocess.run(["git","diff-index","--cached","--quiet","HEAD","--"], cwd=cwd).returncode !=0
    if has_unstaged or has_staged:
        print("error: worktree not clean; use `refresh` or `reset --hard`", file=sys.stderr)
        sys.exit(1)

    if patch_args:
        # pop with specific patches -> final applied = applied minus patch_args
        target_set = set(patch_args)
        final_applied = [p for p in stack["applied"] if p not in target_set]
        final_unapplied = [p for p in stack["applied"] if p in target_set] + stack.get("unapplied",[])
        base = get_base_commit(stack, branch, cwd=cwd)
        current_head = base
        new_patches_map = dict(stack["patches"])
        for pname in final_applied:
            oid = new_patches_map[pname]["oid"]
            temp_branch = f"stg-pop-temp-{pname}"
            subprocess.run(["git","checkout","-b",temp_branch, current_head], cwd=cwd, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            ret = subprocess.run(["git","cherry-pick","--no-commit", oid], cwd=cwd).returncode
            if ret!=0:
                subprocess.run(["git","add","--all"], cwd=cwd)
            try:
                new_tree = run_git_output(["write-tree"], cwd=cwd).strip()
                msg = get_commit_message(oid, cwd=cwd)
                new_commit = git_commit_tree(new_tree, [current_head], msg, cwd=cwd)
            except Exception as e:
                print(f"error: {e}", file=sys.stderr)
                sys.exit(1)
            subprocess.run(["git","checkout", branch], cwd=cwd, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            subprocess.run(["git","branch","-D", temp_branch], cwd=cwd, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            current_head = new_commit
            new_patches_map[pname]={"oid":new_commit}
        # update stack
        new_stack = {
            "version":5,
            "prev":old_tip,
            "head":current_head,
            "applied":final_applied,
            "unapplied":final_unapplied,
            "hidden": stack.get("hidden",[]),
            "patches":new_patches_map
        }
        # rebuild blobs
        existing_blobs = {}
        try:
            out_ls = run_git_output(["ls-tree", old_meta], cwd=cwd)
            old_pt = None
            for line in out_ls.splitlines():
                if "\\tpatches" in line:
                    bt, at = line.split("\\t",1)
                    if at=="patches":
                        old_pt = bt.split()[2]
            if old_pt and old_pt != "4b825dc642cb6eb9a060e54bf8d69288fbee4904":
                out = run_git_output(["ls-tree", old_pt], cwd=cwd)
                for l in out.splitlines():
                    if "\\t" in l:
                        meta, name = l.split("\\t",1)
                        existing_blobs[name]=meta.split()[2]
        except:
            pass
        base_tree = get_tree_of_commit(base, cwd=cwd)
        cur_prev = base_tree
        for pname in final_applied:
            oid = new_patches_map[pname]["oid"]
            top_tree = get_tree_of_commit(oid, cwd=cwd)
            try:
                auth, date = get_commit_author(oid, cwd=cwd)
                msg = get_commit_message(oid, cwd=cwd)
                blob = create_patch_blob(cur_prev, top_tree, auth, date, msg, cwd=cwd)
                existing_blobs[pname]=blob
            except Exception as e:
                print(f"error: {e}", file=sys.stderr)
                sys.exit(1)
            cur_prev = top_tree
        try:
            new_patches_tree = build_patches_tree(existing_blobs, cwd=cwd)
            new_stack_blob = write_stack_json(new_stack, cwd=cwd)
            new_meta_tree = create_tree_with_stack_and_patches(new_stack_blob, new_patches_tree, cwd=cwd)
            new_meta_commit = git_commit_tree(new_meta_tree, [old_meta], "pop", cwd=cwd)
            new_stacks_commit = git_commit_tree(new_meta_tree, [new_meta_commit, current_head, old_tip], "pop", cwd=cwd)
            refname = f"refs/stacks/{branch}"
            run_git_output(["update-ref", refname, new_stacks_commit], cwd=cwd)
            branch_ref = f"refs/heads/{branch}"
            run_git_output(["update-ref", branch_ref, current_head], cwd=cwd)
            subprocess.run(["git","reset","--hard", current_head], cwd=cwd, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            for p in patch_args:
                print(f"- {p}")
            if final_applied:
                print(f"> {final_applied[-1]}")
        except Exception as e:
            print(f"error: {e}", file=sys.stderr)
            sys.exit(1)
        return

    # simple pop
    pop_count = 1
    if all_flag:
        pop_count = len(stack["applied"])
    elif number is not None:
        if number <0:
            keep = -number
            if keep >= len(stack["applied"]):
                pop_count=0
            else:
                pop_count = len(stack["applied"])-keep
        else:
            pop_count = number
    pop_count = min(pop_count, len(stack["applied"]))
    new_applied = stack["applied"][:-pop_count] if pop_count else stack["applied"][:]
    popped = stack["applied"][-pop_count:] if pop_count else []
    popped_rev = list(reversed(popped))
    new_unapplied = popped_rev + stack.get("unapplied",[])
    if not new_applied:
        try:
            new_head = get_base_commit(stack, branch, cwd=cwd)
        except Exception as e:
            print(f"error: {e}", file=sys.stderr)
            sys.exit(1)
    else:
        new_head = stack["patches"][new_applied[-1]]["oid"]
    # update
    branch_ref = f"refs/heads/{branch}"
    try:
        run_git_output(["update-ref", branch_ref, new_head], cwd=cwd)
        subprocess.run(["git","reset","--hard", new_head], cwd=cwd, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        # rebuild stack json but keep blobs same
        existing_blobs = {}
        try:
            out_ls = run_git_output(["ls-tree", old_meta], cwd=cwd)
            old_pt = None
            for line in out_ls.splitlines():
                if "\\tpatches" in line:
                    bt, at = line.split("\\t",1)
                    if at=="patches":
                        old_pt = bt.split()[2]
            if old_pt and old_pt != "4b825dc642cb6eb9a060e54bf8d69288fbee4904":
                out = run_git_output(["ls-tree", old_pt], cwd=cwd)
                for l in out.splitlines():
                    if "\\t" in l:
                        meta, name = l.split("\\t",1)
                        existing_blobs[name]=meta.split()[2]
        except:
            pass
        new_patches_tree = build_patches_tree(existing_blobs, cwd=cwd)
        new_stack = {
            "version":5,
            "prev":old_tip,
            "head":new_head,
            "applied":new_applied,
            "unapplied":new_unapplied,
            "hidden": stack.get("hidden",[]),
            "patches": stack.get("patches",{})
        }
        new_stack_blob = write_stack_json(new_stack, cwd=cwd)
        new_meta_tree = create_tree_with_stack_and_patches(new_stack_blob, new_patches_tree, cwd=cwd)
        new_meta_commit = git_commit_tree(new_meta_tree, [old_meta], "pop", cwd=cwd)
        new_stacks_commit = git_commit_tree(new_meta_tree, [new_meta_commit, new_head, old_tip], "pop", cwd=cwd)
        refname = f"refs/stacks/{branch}"
        run_git_output(["update-ref", refname, new_stacks_commit], cwd=cwd)
        for p in popped_rev:
            print(f"- {p}")
        if new_applied:
            print(f"> {new_applied[-1]}")
    except Exception as e:
        print(f"error: {e}", file=sys.stderr)
        sys.exit(1)

def do_push(patch_args=None, all_flag=False, number=None, cwd=None):
    if patch_args is None:
        patch_args=[]
    branch = get_current_branch(cwd=cwd)
    if not stack_ref_exists(branch, cwd=cwd):
        print("error: no unapplied patches", file=sys.stderr)
        sys.exit(1)
    try:
        stack, old_tip, old_meta = read_stack_json(branch, cwd=cwd)
    except Exception as e:
        print(f"error: {e}", file=sys.stderr)
        sys.exit(1)
    if not stack.get("unapplied") and not patch_args and not all_flag:
        print("error: no unapplied patches", file=sys.stderr)
        sys.exit(1)
    to_push=[]
    if all_flag:
        to_push = stack.get("unapplied",[])[:]
    elif number is not None:
        if number<0:
            keep = -number
            if keep < len(stack.get("unapplied",[])):
                to_push = stack["unapplied"][:len(stack["unapplied"])-keep]
        else:
            to_push = stack["unapplied"][:number]
    elif patch_args:
        to_push = patch_args[:]
    else:
        if stack.get("unapplied"):
            to_push = [stack["unapplied"][0]]
    for p in to_push:
        if p not in stack.get("unapplied",[]):
            print(f"error: patch `{p}` is not unapplied", file=sys.stderr)
            sys.exit(1)
    current_head = stack["head"]
    new_applied = stack.get("applied",[])[:]
    remaining_unapplied = stack.get("unapplied",[])[:]
    new_patches_map = dict(stack.get("patches",{}))
    for pname in to_push:
        old_oid = new_patches_map[pname]["oid"]
        temp_branch = f"stg-push-temp-{pname}"
        subprocess.run(["git","checkout","-b",temp_branch, current_head], cwd=cwd, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        ret = subprocess.run(["git","cherry-pick","--no-commit", old_oid], cwd=cwd).returncode
        if ret!=0:
            subprocess.run(["git","add","--all"], cwd=cwd)
        try:
            new_tree = run_git_output(["write-tree"], cwd=cwd).strip()
            msg = get_commit_message(old_oid, cwd=cwd)
            new_commit = git_commit_tree(new_tree, [current_head], msg, cwd=cwd)
        except Exception as e:
            print(f"error: {e}", file=sys.stderr)
            sys.exit(1)
        subprocess.run(["git","checkout", branch], cwd=cwd, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        subprocess.run(["git","branch","-D", temp_branch], cwd=cwd, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        current_head = new_commit
        new_patches_map[pname]={"oid":new_commit}
        new_applied.append(pname)
        remaining_unapplied = [x for x in remaining_unapplied if x!=pname]
    branch_ref = f"refs/heads/{branch}"
    try:
        run_git_output(["update-ref", branch_ref, current_head], cwd=cwd)
        subprocess.run(["git","reset","--hard", current_head], cwd=cwd, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        # rebuild blobs for all applied
        existing_blobs = {}
        try:
            out_ls = run_git_output(["ls-tree", old_meta], cwd=cwd)
            old_pt = None
            for line in out_ls.splitlines():
                if "\\tpatches" in line:
                    bt, at = line.split("\\t",1)
                    if at=="patches":
                        old_pt = bt.split()[2]
            if old_pt and old_pt != "4b825dc642cb6eb9a060e54bf8d69288fbee4904":
                out = run_git_output(["ls-tree", old_pt], cwd=cwd)
                for l in out.splitlines():
                    if "\\t" in l:
                        meta, name = l.split("\\t",1)
                        existing_blobs[name]=meta.split()[2]
        except:
            pass
        base = get_base_commit(stack, branch, cwd=cwd)
        base_tree = get_tree_of_commit(base, cwd=cwd)
        cur_prev = base_tree
        for pname in new_applied:
            oid = new_patches_map[pname]["oid"]
            top_tree = get_tree_of_commit(oid, cwd=cwd)
            try:
                auth, date = get_commit_author(oid, cwd=cwd)
                msg = get_commit_message(oid, cwd=cwd)
                blob = create_patch_blob(cur_prev, top_tree, auth, date, msg, cwd=cwd)
                existing_blobs[pname]=blob
            except Exception as e:
                print(f"error: {e}", file=sys.stderr)
                sys.exit(1)
            cur_prev = top_tree
        new_patches_tree = build_patches_tree(existing_blobs, cwd=cwd)
        new_stack = {
            "version":5,
            "prev": old_tip,
            "head": current_head,
            "applied": new_applied,
            "unapplied": remaining_unapplied,
            "hidden": stack.get("hidden",[]),
            "patches": new_patches_map
        }
        new_stack_blob = write_stack_json(new_stack, cwd=cwd)
        new_meta_tree = create_tree_with_stack_and_patches(new_stack_blob, new_patches_tree, cwd=cwd)
        new_meta_commit = git_commit_tree(new_meta_tree, [old_meta], "push", cwd=cwd)
        new_stacks_commit = git_commit_tree(new_meta_tree, [new_meta_commit, current_head, old_tip], "push", cwd=cwd)
        refname = f"refs/stacks/{branch}"
        run_git_output(["update-ref", refname, new_stacks_commit], cwd=cwd)
        for p in to_push:
            print(f"> {p}")
    except Exception as e:
        print(f"error: {e}", file=sys.stderr)
        sys.exit(1)

def do_series(patch_filter=None, branch_opt=None, color_mode="auto", all_flag=False, short=None, applied=False, unapplied=False, hidden=False, missing=None, author=False, count=False, commit_id=None, description=False, empty=False, reverse=False, cwd=None):
    if patch_filter is None:
        patch_filter=[]
    branch = branch_opt if branch_opt else get_current_branch(cwd=cwd)
    if not stack_ref_exists(branch, cwd=cwd):
        return
    try:
        stack, _, _ = read_stack_json(branch, cwd=cwd)
    except Exception as e:
        print(f"error: {e}", file=sys.stderr)
        sys.exit(1)
    selected=[]
    top_name = stack["applied"][-1] if stack.get("applied") else None
    for name in stack.get("applied",[]):
        prefix = ">" if name==top_name else "+"
        if applied and not all_flag:
            selected.append((name,prefix))
        elif not unapplied and not hidden and not applied and not patch_filter and not all_flag:
            selected.append((name,prefix))
        elif all_flag or applied:
            selected.append((name,prefix))
        elif patch_filter:
            if name in patch_filter:
                selected.append((name,prefix))
        else:
            selected.append((name,prefix))
    for name in stack.get("unapplied",[]):
        if unapplied or all_flag or (not applied and not hidden and not patch_filter):
            if not patch_filter or name in patch_filter:
                selected.append((name,"-"))
    for name in stack.get("hidden",[]):
        if hidden or all_flag:
            if not patch_filter or name in patch_filter:
                selected.append((name,"!"))
    # short handling
    if short is not None:
        # short is tuple (is_flag, value)
        # For simplicity, if short is not None, value is number or None meaning default
        n = 5
        if isinstance(short, int):
            n = short
        elif isinstance(short, tuple):
            # (has_value, val)
            if short[1] is not None:
                n = short[1]
        # find top idx
        top_idx = None
        for idx,(nm,pfx) in enumerate(selected):
            if pfx==">":
                top_idx=idx
                break
        if top_idx is not None and n>0:
            start = max(0, top_idx-n)
            end = min(len(selected), top_idx+n+1)
            selected = selected[start:end]
    if reverse:
        selected = list(reversed(selected))
    if count:
        print(len(selected))
        return
    use_color = should_use_color(color_mode)
    for name,prefix in selected:
        empty_marker = ""
        if empty:
            try:
                oid = stack["patches"][name]["oid"]
                parent_out = run_git_output(["log","-1","--pretty=%P", oid], cwd=cwd).strip()
                parent = parent_out.split()[0] if parent_out else ""
                if parent:
                    pt = get_tree_of_commit(parent, cwd=cwd)
                    tt = get_tree_of_commit(oid, cwd=cwd)
                    empty_marker = "0" if pt==tt else " "
                else:
                    empty_marker=" "
            except:
                empty_marker=" "
        line=""
        if empty:
            line+=empty_marker
        line+=prefix+" "
        extra=""
        if commit_id is not None:
            try:
                oid = stack["patches"][name]["oid"]
                disp = oid
                if isinstance(commit_id, tuple):
                    # (has_len, len_str)
                    has_len, len_val = commit_id
                    if has_len and len_val and len_val!="full":
                        try:
                            l = int(len_val)
                            if l>=4 and l<=len(oid):
                                disp = oid[:l]
                        except:
                            pass
                extra+=disp+" "
            except:
                pass
        if description:
            try:
                oid = stack["patches"][name]["oid"]
                msg = run_git_output(["log","-1","--pretty=%s", oid], cwd=cwd).strip()
                extra+=f"# {msg} "
            except:
                pass
            line+=extra+name
        elif author:
            try:
                oid = stack["patches"][name]["oid"]
                auth = run_git_output(["log","-1","--pretty=%an", oid], cwd=cwd).strip()
                line+=f"{extra}{name} {auth}"
            except:
                line+=f"{extra}{name}"
        else:
            if extra:
                line+=extra+name
            else:
                line+=name
        if use_color:
            # colorize
            if prefix=="+":
                colored = f"\\x1b[0m\\x1b[32m{prefix} \\x1b[0m\\x1b[0m{name}"
            elif prefix==">":
                colored = f"\\x1b[0m\\x1b[34m{prefix} \\x1b[0m\\x1b[0m\\x1b[1m{name}\\x1b[0m"
            elif prefix=="-":
                colored = f"\\x1b[0m\\x1b[31m{prefix} \\x1b[0m\\x1b[0m{name}"
            else:
                colored = f"\\x1b[0m\\x1b[33m{prefix} \\x1b[0m\\x1b[0m{name}"
            if commit_id is not None or description or author:
                print(line)
            else:
                # if empty flag
                if empty:
                    # need to include empty marker
                    print(f"{empty_marker}{colored}")
                else:
                    print(colored)
        else:
            print(line)

