def do_undo(number=None, hard=False, cwd=None):
    branch = get_current_branch(cwd=cwd)
    if not stack_ref_exists(branch, cwd=cwd):
        print("error: no undo information", file=sys.stderr)
        sys.exit(1)
    try:
        stack, tip, _ = read_stack_json(branch, cwd=cwd)
    except Exception as e:
        print("error: no undo information", file=sys.stderr)
        sys.exit(1)
    count = number if number else 1
    current = tip
    target_stack=None
    target_tip=None
    for _ in range(count):
        try:
            parents_out = run_git_output(["log","-1","--pretty=%P", current], cwd=cwd).strip()
            parents = parents_out.split()
            if not parents:
                break
            meta_commit = parents[0]
            out_ls = run_git_output(["ls-tree", meta_commit], cwd=cwd)
            blob_oid=None
            for line in out_ls.splitlines():
                if "stack.json" in line:
                    if "\\t" in line:
                        before, after = line.split("\\t",1)
                        if after=="stack.json":
                            blob_oid = before.split()[2]
                    else:
                        parts=line.split()
                        if len(parts)>=3:
                            blob_oid=parts[2]
            if not blob_oid:
                break
            content = run_git_output(["cat-file","-p", blob_oid], cwd=cwd)
            data = json.loads(content)
            prev = data.get("prev")
            if not prev:
                break
            # get prev's stack
            parents_out2 = run_git_output(["log","-1","--pretty=%P", prev], cwd=cwd).strip()
            parents2 = parents_out2.split()
            if not parents2:
                break
            meta2 = parents2[0]
            out_ls2 = run_git_output(["ls-tree", meta2], cwd=cwd)
            blob2=None
            for line in out_ls2.splitlines():
                if "stack.json" in line:
                    if "\\t" in line:
                        before, after = line.split("\\t",1)
                        if after=="stack.json":
                            blob2 = before.split()[2]
                    else:
                        parts=line.split()
                        if len(parts)>=3:
                            blob2=parts[2]
            if not blob2:
                break
            content2 = run_git_output(["cat-file","-p", blob2], cwd=cwd)
            data2 = json.loads(content2)
            target_stack = data2
            target_tip = prev
            current = prev
        except Exception as e:
            break
    if target_stack and target_tip:
        branch_ref = f"refs/heads/{branch}"
        try:
            run_git_output(["update-ref", branch_ref, target_stack["head"]], cwd=cwd)
            if hard:
                subprocess.run(["git","reset","--hard", target_stack["head"]], cwd=cwd, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            else:
                subprocess.run(["git","reset","--mixed", target_stack["head"]], cwd=cwd, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            refname = f"refs/stacks/{branch}"
            run_git_output(["update-ref", refname, target_tip], cwd=cwd)
            if target_stack.get("applied"):
                print(f"> {target_stack['applied'][-1]}")
        except Exception as e:
            print(f"error: {e}", file=sys.stderr)
            sys.exit(1)
    else:
        print("error: no undo information", file=sys.stderr)
        sys.exit(1)

def main():
    # Parse global -C options manually before subcommand
    args = sys.argv[1:]
    c_paths = []
    color_mode = "auto"
    # Need to handle -C <path> which can be multiple
    # Also need to handle --color <when>
    # And --version, -h/--help
    # We'll process sequentially
    i=0
    remaining=[]
    while i < len(args):
        a = args[i]
        if a == "-C":
            if i+1 < len(args):
                c_paths.append(args[i+1])
                i+=2
            else:
                i+=1
        elif a.startswith("-C") and len(a)>2:
            # -C<path>
            c_paths.append(a[2:])
            i+=1
        elif a == "--color":
            if i+1 < len(args):
                color_mode = args[i+1]
                i+=2
            else:
                i+=1
        elif a.startswith("--color="):
            color_mode = a.split("=",1)[1]
            i+=1
        elif a == "--version":
            print_version(False, color_mode)
            sys.exit(0)
        elif a in ("-h","--help"):
            # If no subcommand yet, print main help
            # Check if remaining has subcommand? For simplicity, if no subcommand in remaining, print main help
            # If there is subcommand before help? Original help handling: stg [OPTIONS] <-h|--help> prints main help regardless?
            # For subcommand help, like "stg series --help", our loop will encounter subcommand first then --help.
            # So we need to detect subcommand before help.
            # We'll handle below after loop.
            remaining.append(a)
            i+=1
        else:
            remaining.append(a)
            i+=1

    # Handle -C paths: change cwd accordingly
    cwd = os.getcwd()
    for p in c_paths:
        if not os.path.isabs(p):
            cwd = os.path.join(cwd, p)
