    def get_opt(args, *names):
        # names like "-m", "--message"
        for i,arg in enumerate(args):
            if arg in names:
                if i+1 < len(args):
                    return args[i+1]
            if any(arg.startswith(n+"=") for n in names):
                for n in names:
                    if arg.startswith(n+"="):
