def do_id(rev_opt=None, branch_opt=None, cwd=None):
    branch=branch_opt if branch_opt else get_current_branch(cwd=cwd)
    if not stack_ref_exists(branch, cwd=cwd):
        print("error: patch `base` does not exist", file=sys.stderr)
        sys.exit(1)
    stack,_,_ = read_stack_json(branch, cwd=cwd)
    rev=rev_opt or ""
    if not rev:
        if stack.get("applied"):
            print(stack["patches"][stack["applied"][-1]]["oid"])
        else:
            print(stack["head"])
        return
    if rev=="{base}":
        print(get_base_commit(stack, branch, cwd=cwd))
        return
    if ":{base}" in rev:
        b=rev.split(":",1)[0]
        if stack_ref_exists(b, cwd=cwd):
            s,_,_ = read_stack_json(b, cwd=cwd)
            print(get_base_commit(s,b,cwd=cwd))
            return
        else:
            print("error: patch `base` does not exist", file=sys.stderr)
            sys.exit(1)
    if rev.endswith("^"):
        patch_name=rev[:-1]
        if ":" in patch_name:
            b,p=patch_name.split(":",1)
        else:
            b=branch
            p=patch_name
        try:
            if b!=branch:
                s,_,_ = read_stack_json(b, cwd=cwd)
            else:
                s=stack
            oid=s["patches"][p]["oid"]
            out=run_git_output(["log","-1","--pretty=%P", oid], cwd=cwd).strip()
            parent=out.split()[0] if out else ""
            print(parent)
            return
        except:
            try:
                out=run_git_output(["rev-parse", rev], cwd=cwd).strip()
                print(out)
                return
            except:
                print(f"error: patch `{p}` does not exist", file=sys.stderr)
                sys.exit(1)
    if ":" in rev:
        b,p=rev.split(":",1)
        if p=="{base}":
            if stack_ref_exists(b, cwd=cwd):
                s,_,_ = read_stack_json(b, cwd=cwd)
                print(get_base_commit(s,b,cwd=cwd))
                return
            else:
                print("error: patch `base` does not exist", file=sys.stderr)
                sys.exit(1)
        else:
            if stack_ref_exists(b, cwd=cwd):
                s,_,_ = read_stack_json(b, cwd=cwd)
                if p in s["patches"]:
                    print(s["patches"][p]["oid"])
                    return
            print(f"error: patch `{p}` does not exist", file=sys.stderr)
            sys.exit(1)
    if rev in stack.get("patches",{}):
        print(stack["patches"][rev]["oid"])
        return
    try:
        out=run_git_output(["rev-parse", rev], cwd=cwd).strip()
        print(out)
    except:
        print(f"error: patch `{rev}` does not exist", file=sys.stderr)
        sys.exit(1)

