                parts=line.split()
                if len(parts)>=3:
                    stack_blob=parts[2]
    if not stack_blob:
        raise Exception("stack.json not found")
    content = run_git_output(["cat-file","-p", stack_blob], cwd=cwd)
    data=json.loads(content)
    return data, tip, meta_commit

def write_stack_json(data, cwd=None):
    json_str=json.dumps(data, indent=2)
    proc=subprocess.Popen(["git","hash-object","-w","--stdin"], cwd=cwd, stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
    out,err=proc.communicate(json_str)
    if proc.returncode!=0:
        raise Exception(err)
    return out.strip()

def create_tree_with_stack_and_patches(stack_blob_oid, patches_tree_oid, cwd=None):
    input_lines=""
    if patches_tree_oid and patches_tree_oid!="4b825dc642cb6eb9a060e54bf8d69288fbee4904":
        input_lines+=f"040000 tree {patches_tree_oid}\\tpatches\\n"
    input_lines+=f"100644 blob {stack_blob_oid}\\tstack.json\\n"
    proc=subprocess.Popen(["git","mktree"], cwd=cwd, stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
    out,err=proc.communicate(input_lines)
    if proc.returncode!=0:
        raise Exception(err)
    return out.strip()

def build_patches_tree(patches_dict, cwd=None):
    if not patches_dict:
        return "4b825dc642cb6eb9a060e54bf8d69288fbee4904"
    input_lines=""
    for name in sorted(patches_dict.keys()):
        oid=patches_dict[name]
        input_lines+=f"100644 blob {oid}\\t{name}\\n"
    proc=subprocess.Popen(["git","mktree"], cwd=cwd, stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
    out,err=proc.communicate(input_lines)
    if proc.returncode!=0:
        raise Exception(err)
    return out.strip()

def create_patch_blob(bottom, top, author, date, message, cwd=None):
    content=f"Bottom: {bottom}\\nTop:    {top}\\nAuthor: {author}\\nDate:   {date}\\n\\n{message}\\n"
    proc=subprocess.Popen(["git","hash-object","-w","--stdin"], cwd=cwd, stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
    out,err=proc.communicate(content)
    if proc.returncode!=0:
        raise Exception(err)
    return out.strip()

def git_commit_tree(tree_oid, parents, message, cwd=None):
    args=["commit-tree", tree_oid]
    for p in parents:
        args.extend(["-p", p])
    args.extend(["-m", message])
    result=subprocess.run(["git"]+args, cwd=cwd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
    if result.returncode!=0:
        raise Exception(result.stderr)
    return result.stdout.strip()

def get_current_head(cwd=None):
    out=run_git_output(["rev-parse","HEAD"], cwd=cwd)
    return out.strip()

def get_tree_of_commit(commit, cwd=None):
    out=run_git_output(["log","-1","--pretty=%T", commit], cwd=cwd)
    return out.strip()

def get_commit_message(commit, cwd=None):
    out=run_git_output(["log","-1","--pretty=%B", commit], cwd=cwd)
    return out.rstrip("\\n")

def get_commit_author(commit, cwd=None):
    out_author=run_git_output(["log","-1","--pretty=%an <%ae>", commit], cwd=cwd).strip()
    out_date=run_git_output(["log","-1","--pretty=%ai", commit], cwd=cwd).strip()
    return out_author, out_date

def get_base_commit(stack, branch, cwd=None):
    if not stack.get("applied"):
        return stack.get("head")
    bottom=stack["applied"][0]
    oid=stack["patches"][bottom]["oid"]
    out=run_git_output(["log","-1","--pretty=%P", oid], cwd=cwd)
    parent=out.strip().split()
    if not parent:
        return oid
    return parent[0]

def should_use_color(mode):
    if mode=="always":
        return True
    if mode=="never":
        return False
    if mode=="ansi":
        return True
    if os.getenv("NO_COLOR"):
        return False
    return sys.stdout.isatty()

