def do_diff(path_args=None, range_opt=None, stat=False, diff_opt=None, cwd=None):
    if path_args is None:
        path_args=[]
    if diff_opt is None:
        diff_opt=[]
    if range_opt:
        r=range_opt
        if ".." in r:
            parts=r.split("..")
            rev1=parts[0]
            rev2=parts[1] if len(parts)>1 else ""
            args=["diff"]
            if stat:
                args.append("--stat")
            args.extend(diff_opt)
            rev1_resolved=rev1
            try:
                branch=get_current_branch(cwd=cwd)
                if stack_ref_exists(branch, cwd=cwd):
                    stack,_,_ = read_stack_json(branch, cwd=cwd)
                    if rev1 in stack.get("patches",{}):
                        rev1_resolved=stack["patches"][rev1]["oid"]
                    elif rev1=="{base}":
                        rev1_resolved=get_base_commit(stack, branch, cwd=cwd)
                    else:
                        rev1_resolved=run_git_output(["rev-parse", rev1], cwd=cwd).strip()
            except:
                try:
                    rev1_resolved=run_git_output(["rev-parse", rev1], cwd=cwd).strip()
                except:
                    pass
            if not rev2:
                args.append(rev1_resolved)
                if path_args:
                    args.append("--")
                    args.extend(path_args)
            else:
                rev2_resolved=rev2
                try:
                    branch=get_current_branch(cwd=cwd)
                    if stack_ref_exists(branch, cwd=cwd):
                        stack,_,_ = read_stack_json(branch, cwd=cwd)
                        if rev2 in stack.get("patches",{}):
                            rev2_resolved=stack["patches"][rev2]["oid"]
                        elif rev2=="{base}":
                            rev2_resolved=get_base_commit(stack, branch, cwd=cwd)
                        else:
                            rev2_resolved=run_git_output(["rev-parse", rev2], cwd=cwd).strip()
                except:
                    try:
                        rev2_resolved=run_git_output(["rev-parse", rev2], cwd=cwd).strip()
                    except:
                        pass
                args.append(rev1_resolved)
                args.append(rev2_resolved)
                if path_args:
                    args.append("--")
                    args.extend(path_args)
            subprocess.run(["git"]+args, cwd=cwd)
        else:
            rev_resolved=r
            try:
                branch=get_current_branch(cwd=cwd)
                if stack_ref_exists(branch, cwd=cwd):
                    stack,_,_ = read_stack_json(branch, cwd=cwd)
                    if r in stack.get("patches",{}):
                        rev_resolved=stack["patches"][r]["oid"]
                    elif r=="{base}":
                        rev_resolved=get_base_commit(stack, branch, cwd=cwd)
                    else:
                        rev_resolved=run_git_output(["rev-parse", r], cwd=cwd).strip()
            except:
                try:
                    rev_resolved=run_git_output(["rev-parse", r], cwd=cwd).strip()
                except:
                    pass
            args=["diff"]
            if stat:
                args.append("--stat")
            args.extend(diff_opt)
            args.append(rev_resolved)
            if path_args:
                args.append("--")
                args.extend(path_args)
            subprocess.run(["git"]+args, cwd=cwd)
    else:
        args=["diff"]
        if stat:
            args.append("--stat")
        args.extend(diff_opt)
        args.append("HEAD")
        if path_args:
            args.append("--")
            args.extend(path_args)
        subprocess.run(["git"]+args, cwd=cwd)

def do_files(rev_opt=None, stat=False, branch_opt=None, cwd=None):
    branch=branch_opt if branch_opt else get_current_branch(cwd=cwd)
    if not stack_ref_exists(branch, cwd=cwd):
        print("error: no patches applied", file=sys.stderr)
        sys.exit(1)
    stack,_,_ = read_stack_json(branch, cwd=cwd)
    target_rev=rev_opt
    if not target_rev:
        if not stack.get("applied"):
            print("error: no patches applied", file=sys.stderr)
            sys.exit(1)
        target_rev=stack["patches"][stack["applied"][-1]]["oid"]
    if target_rev in stack.get("patches",{}):
        commit_oid=stack["patches"][target_rev]["oid"]
    else:
        try:
            commit_oid=run_git_output(["rev-parse", target_rev], cwd=cwd).strip()
        except:
            print(f"error: patch `{target_rev}` does not exist", file=sys.stderr)
            sys.exit(1)
    parent_out=run_git_output(["log","-1","--pretty=%P", commit_oid], cwd=cwd).strip()
    parent=parent_out.split()[0] if parent_out else ""
    if not parent:
        return
    args=["diff","--name-only", parent, commit_oid]
    if stat:
        args=["diff","--name-status", parent, commit_oid]
    subprocess.run(["git"]+args, cwd=cwd)

def do_show(patch_or_rev=None, patch_opt=None, branch_opt=None, stat=False, diff_opt=None, applied=False, unapplied=False, hidden=False, cwd=None):
    if patch_or_rev is None:
        patch_or_rev=[]
    if patch_opt is None:
        patch_opt=[]
    if diff_opt is None:
        diff_opt=[]
    branch=branch_opt if branch_opt else get_current_branch(cwd=cwd)
    if not stack_ref_exists(branch, cwd=cwd):
        print("error: no patches applied", file=sys.stderr)
        sys.exit(1)
    stack,_,_ = read_stack_json(branch, cwd=cwd)
    revs=[]
    revs.extend(patch_or_rev)
    revs.extend(patch_opt)
    if not revs:
        if applied:
            revs=stack.get("applied",[])[:]
        elif unapplied:
            revs=stack.get("unapplied",[])[:]
        elif hidden:
            revs=stack.get("hidden",[])[:]
        else:
            if stack.get("applied"):
                revs=[stack["applied"][-1]]
            else:
                print("error: no patches applied", file=sys.stderr)
                sys.exit(1)
    expanded=[]
    for r in revs:
        if ".." in r:
            begin,end=r.split("..",1)
            all_p=stack.get("applied",[])+stack.get("unapplied",[])+stack.get("hidden",[])
            b_idx=all_p.index(begin) if begin in all_p else 0
            e_idx=all_p.index(end) if end in all_p else len(all_p)-1
            for idx in range(b_idx, e_idx+1):
                expanded.append(all_p[idx])
        else:
            expanded.append(r)
    for rev in expanded:
        if rev in stack.get("patches",{}):
            commit_oid=stack["patches"][rev]["oid"]
        else:
            try:
                commit_oid=run_git_output(["rev-parse", rev], cwd=cwd).strip()
            except:
                print(f"error: patch `{rev}` does not exist", file=sys.stderr)
                continue
        args=["show"]
        if stat:
            args.append("--stat")
        args.extend(diff_opt)
        args.append(commit_oid)
        subprocess.run(["git"]+args, cwd=cwd)

def do_log(patch_filter=None, branch_opt=None, diff=False, number=None, full=False, graphical=False, clear=False, cwd=None):
    if patch_filter is None:
        patch_filter=[]
    branch=branch_opt if branch_opt else get_current_branch(cwd=cwd)
    if not stack_ref_exists(branch, cwd=cwd):
        return
    stack, tip, _ = read_stack_json(branch, cwd=cwd)
    if clear:
        return
    current=tip
    count=0
    while current:
        if number is not None and count>=number:
            break
        try:
            out=run_git_output(["log","-1","--pretty=format:%h   %ad   %s","--date=rfc", current], cwd=cwd)
            print(out)
        except:
            pass
        try:
            parents_out=run_git_output(["log","-1","--pretty=%P", current], cwd=cwd).strip()
            parents=parents_out.split()
            if not parents:
                break
            meta_commit=parents[0]
            out_ls=run_git_output(["ls-tree", meta_commit], cwd=cwd)
            blob_oid=None
            for line in out_ls.splitlines():
                if "stack.json" in line:
                    if "\\t" in line:
                        before, after = line.split("\\t",1)
                        if after=="stack.json":
                            blob_oid=before.split()[2]
                    else:
                        parts=line.split()
                        if len(parts)>=3:
                            blob_oid=parts[2]
            if not blob_oid:
                break
            content=run_git_output(["cat-file","-p", blob_oid], cwd=cwd)
            data=json.loads(content)
            prev=data.get("prev")
            current=prev
        except:
            break
        count+=1

def do_branch(branch_arg=None, list_flag=False, create=None, clone_opt=None, delete=None, cleanup=None, merge=False, force=False, extra=None, cwd=None):
    if extra is None:
        extra=[]
    if list_flag:
        try:
            out=run_git_output(["branch","--list"], cwd=cwd)
            for line in out.splitlines():
                clean=line.strip().lstrip("* ").strip()
                is_current=line.strip().startswith("*")
                has_stack=stack_ref_exists(clean, cwd=cwd)
                marker="s" if has_stack else " "
                if is_current:
                    print(f"> {marker} \\t{clean}  |")
                else:
                    print(f"  {marker} \\t{clean}  |")
        except Exception as e:
            print(f"error: {e}", file=sys.stderr)
            sys.exit(1)
        return
    if create:
        committish=extra[0] if extra else "HEAD"
        ret=subprocess.run(["git","branch", create, committish], cwd=cwd).returncode
        if ret!=0:
            sys.exit(1)
        subprocess.run(["git","checkout", create], cwd=cwd, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        if not stack_ref_exists(create, cwd=cwd):
            do_init(create, cwd=cwd)
        return
    if clone_opt is not None:
        new_branch_name=clone_opt if isinstance(clone_opt, str) and clone_opt else None
        if not new_branch_name:
            try:
                cur=get_current_branch(cwd=cwd)
                new_branch_name=f"{cur}-clone-{int(time.time())}"
            except:
                new_branch_name=f"clone-{int(time.time())}"
        try:
            cur_branch=get_current_branch(cwd=cwd)
            cur_head=get_current_head(cwd=cwd)
            subprocess.run(["git","branch", new_branch_name, cur_head], cwd=cwd)
            if stack_ref_exists(cur_branch, cwd=cwd):
                tip=get_stack_tip(cur_branch, cwd=cwd)
                refname=f"refs/stacks/{new_branch_name}"
                run_git_output(["update-ref", refname, tip], cwd=cwd)
                out=run_git_output(["show-ref"], cwd=cwd)
                for line in out.splitlines():
                    if f"refs/patches/{cur_branch}/" in line:
                        h, ref = line.split()
                        new_ref=ref.replace(f"refs/patches/{cur_branch}/", f"refs/patches/{new_branch_name}/")
                        run_git_output(["update-ref", new_ref, h], cwd=cwd)
            subprocess.run(["git","checkout", new_branch_name], cwd=cwd, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        except Exception as e:
            print(f"error: {e}", file=sys.stderr)
            sys.exit(1)
        return
    if delete is not None:
        branch_to_del=delete if isinstance(delete, str) and delete else (branch_arg if branch_arg else None)
        if not branch_to_del:
            print("error: branch name required", file=sys.stderr)
            sys.exit(1)
        args=["branch","-D" if force else "-d", branch_to_del]
        ret=subprocess.run(["git"]+args, cwd=cwd).returncode
        if ret!=0:
            sys.exit(1)
        refname=f"refs/stacks/{branch_to_del}"
        subprocess.run(["git","update-ref","-d", refname], cwd=cwd, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        return
    if cleanup is not None:
        branch_to_clean=cleanup if isinstance(cleanup, str) and cleanup else get_current_branch(cwd=cwd)
        refname=f"refs/stacks/{branch_to_clean}"
        subprocess.run(["git","update-ref","-d", refname], cwd=cwd, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        return
    if branch_arg:
        ret=subprocess.run(["git","checkout", branch_arg], cwd=cwd).returncode
        if ret!=0:
            sys.exit(1)
        print(branch_arg)
        return
    try:
        cur=get_current_branch(cwd=cwd)
        print(cur)
    except Exception as e:
        print(f"error: {e}", file=sys.stderr)
        sys.exit(1)

def do_export(patch=None, branch_opt=None, dir_opt=None, patch_suffix=False, extension=None, numbered=False, stdout_flag=False, diff_opt=None, cwd=None):
    if patch is None:
        patch=[]
    if diff_opt is None:
        diff_opt=[]
    branch=branch_opt if branch_opt else get_current_branch(cwd=cwd)
    if not stack_ref_exists(branch, cwd=cwd):
        return
    stack,_,_ = read_stack_json(branch, cwd=cwd)
    if not patch:
        patches_to_export=stack.get("applied",[])+stack.get("unapplied",[])
    else:
        patches_to_export=[]
        for p in patch:
            if ".." in p:
                begin,end=p.split("..",1)
                all_p=stack.get("applied",[])+stack.get("unapplied",[])
                b_idx=all_p.index(begin) if begin in all_p else 0
                e_idx=all_p.index(end) if end in all_p else len(all_p)-1
                for idx in range(b_idx, e_idx+1):
                    patches_to_export.append(all_p[idx])
            else:
                patches_to_export.append(p)
    out_dir=dir_opt if dir_opt else f"patches-{branch}"
    if not stdout_flag:
        os.makedirs(out_dir, exist_ok=True)
        series_path=os.path.join(out_dir, "series")
        series_content=""
        for i,pname in enumerate(patches_to_export):
            filename=f"{i+1:02d}-{pname}" if numbered else pname
            suffix=""
            if patch_suffix:
                suffix=".patch"
            elif extension:
                suffix=f".{extension}"
            series_content+=f"{filename}{suffix}\\n"
        try:
            with open(series_path,"w") as f:
                f.write(series_content)
        except:
            pass
    for i,pname in enumerate(patches_to_export):
        try:
            oid=stack["patches"][pname]["oid"]
            content=run_git_output(["show", oid], cwd=cwd)
        except:
            continue
        if stdout_flag:
            print(content)
        else:
            filename=f"{i+1:02d}-{pname}" if numbered else pname
            suffix=""
            if patch_suffix:
                suffix=".patch"
            elif extension:
                suffix=f".{extension}"
            filepath=os.path.join(out_dir, f"{filename}{suffix}")
            try:
                with open(filepath,"w") as f:
                    f.write(content)
            except:
                pass

def do_patches(path=None, branch_opt=None, diff_flag=False, diff_opt=None, cwd=None):
    if path is None:
        path=[]
    if diff_opt is None:
        diff_opt=[]
    branch=branch_opt if branch_opt else get_current_branch(cwd=cwd)
    if not stack_ref_exists(branch, cwd=cwd):
        return
    stack,_,_ = read_stack_json(branch, cwd=cwd)
    if not path:
        try:
            out=run_git_output(["diff","--name-only","HEAD"], cwd=cwd)
            target_paths=out.splitlines()
        except:
            target_paths=[]
    else:
        target_paths=path
    for pname in stack.get("applied",[]):
        try:
            oid=stack["patches"][pname]["oid"]
            parent_out=run_git_output(["log","-1","--pretty=%P", oid], cwd=cwd).strip()
            parent=parent_out.split()[0] if parent_out else ""
            if not parent:
                continue
            out=run_git_output(["diff","--name-only", parent, oid], cwd=cwd)
            modified=out.splitlines()
            if any(tp in modified for tp in target_paths):
                if diff_flag:
                    subprocess.run(["git","show", oid], cwd=cwd)
                else:
                    print(pname)
        except:
            continue

def do_undo(number=None, hard=False, cwd=None):
    branch=get_current_branch(cwd=cwd)
    if not stack_ref_exists(branch, cwd=cwd):
        print("error: no undo information", file=sys.stderr)
        sys.exit(1)
    stack, tip, _ = read_stack_json(branch, cwd=cwd)
    count=number if number else 1
    current=tip
    target_stack=None
    target_tip=None
    for _ in range(count):
        try:
            parents_out=run_git_output(["log","-1","--pretty=%P", current], cwd=cwd).strip()
            parents=parents_out.split()
            if not parents:
                break
            meta_commit=parents[0]
            out_ls=run_git_output(["ls-tree", meta_commit], cwd=cwd)
            blob_oid=None
            for line in out_ls.splitlines():
                if "stack.json" in line:
                    if "\\t" in line:
                        before, after = line.split("\\t",1)
                        if after=="stack.json":
                            blob_oid=before.split()[2]
                    else:
                        parts=line.split()
                        if len(parts)>=3:
                            blob_oid=parts[2]
            if not blob_oid:
                break
            content=run_git_output(["cat-file","-p", blob_oid], cwd=cwd)
            data=json.loads(content)
            prev=data.get("prev")
            if not prev:
                break
            parents_out2=run_git_output(["log","-1","--pretty=%P", prev], cwd=cwd).strip()
            parents2=parents_out2.split()
            if not parents2:
                break
            meta2=parents2[0]
            out_ls2=run_git_output(["ls-tree", meta2], cwd=cwd)
            blob2=None
            for line in out_ls2.splitlines():
                if "stack.json" in line:
                    if "\\t" in line:
                        before, after = line.split("\\t",1)
                        if after=="stack.json":
                            blob2=before.split()[2]
                    else:
                        parts=line.split()
                        if len(parts)>=3:
                            blob2=parts[2]
            if not blob2:
                break
            content2=run_git_output(["cat-file","-p", blob2], cwd=cwd)
            data2=json.loads(content2)
            target_stack=data2
            target_tip=prev
            current=prev
        except:
            break
    if target_stack and target_tip:
        branch_ref=f"refs/heads/{branch}"
        try:
            run_git_output(["update-ref", branch_ref, target_stack["head"]], cwd=cwd)
            if hard:
                subprocess.run(["git","reset","--hard", target_stack["head"]], cwd=cwd, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            else:
                subprocess.run(["git","reset","--mixed", target_stack["head"]], cwd=cwd, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            refname=f"refs/stacks/{branch}"
            run_git_output(["update-ref", refname, target_tip], cwd=cwd)
            if target_stack.get("applied"):
                print(f"> {target_stack['applied'][-1]}")
        except Exception as e:
            print(f"error: {e}", file=sys.stderr)
            sys.exit(1)
    else:
        print("error: no undo information", file=sys.stderr)
        sys.exit(1)

def main():
    args = sys.argv[1:]
    c_paths = []
    color_mode = "auto"
    i=0
    remaining=[]
    while i < len(args):
        a = args[i]
        if a == "-C":
            if i+1 < len(args):
                c_paths.append(args[i+1])
                i+=2
            else:
                i+=1
        elif a.startswith("-C") and len(a)>2:
            c_paths.append(a[2:])
            i+=1
        elif a == "--color":
            if i+1 < len(args):
                color_mode = args[i+1]
                i+=2
            else:
                i+=1
        elif a.startswith("--color="):
            color_mode = a.split("=",1)[1]
            i+=1
        elif a == "--version":
            print_version(False, color_mode)
            sys.exit(0)
        else:
            remaining.append(a)
            i+=1

    cwd = os.getcwd()
    for p in c_paths:
        if not os.path.isabs(p):
            cwd = os.path.join(cwd, p)
        else:
            cwd = p
    if c_paths:
        try:
            os.chdir(cwd)
        except:
            pass

    if not remaining:
        print(MAIN_HELP)
        sys.exit(0)

    if len(remaining)==1 and remaining[0] in ("-h","--help"):
        print(MAIN_HELP)
        sys.exit(0)

    if remaining[0]=="help":
        if len(remaining)>=2:
            sub = remaining[1]
            if sub in HELP_TEXTS:
                print(HELP_TEXTS[sub])
                sys.exit(0)
            else:
                print(MAIN_HELP)
                sys.exit(0)
        else:
            print(MAIN_HELP)
            sys.exit(0)

    subcommand = remaining[0]
    sub_args = remaining[1:]

    if subcommand in ("-h","--help"):
        print(MAIN_HELP)
        sys.exit(0)

    if "-h" in sub_args or "--help" in sub_args:
        if subcommand in HELP_TEXTS:
            print(HELP_TEXTS[subcommand])
            sys.exit(0)
        else:
            if subcommand.startswith("-"):
                print(f"error: unrecognized subcommand '{subcommand}'", file=sys.stderr)
                print("\\nUsage: stg [OPTIONS] <command> [...]", file=sys.stderr)
                print("       stg [OPTIONS] <-h|--help>", file=sys.stderr)
                print("       stg --version", file=sys.stderr)
                print("\\nFor more information, try '--help'.", file=sys.stderr)
                sys.exit(1)
            print(MAIN_HELP)
            sys.exit(0)

    # helpers for parsing sub_args
    def has_flag(args, *flags):
        for f in flags:
            if f in args:
                return True
        return False
    def get_opt(args, *names):
        for i,arg in enumerate(args):
            if arg in names:
                if i+1 < len(args):
                    return args[i+1]
            if any(arg.startswith(n+"=") for n in names):
                for n in names:
                    if arg.startswith(n+"="):
                        return arg.split("=",1)[1]
        return None
    def get_all_opts(args, *names):
        res=[]
        for i,arg in enumerate(args):
            if arg in names:
                if i+1 < len(args):
                    res.append(args[i+1])
            if any(arg.startswith(n+"=") for n in names):
                for n in names:
                    if arg.startswith(n+"="):
                        res.append(arg.split("=",1)[1])
        return res

    cwd=None

    if subcommand == "version":
        short = has_flag(sub_args, "-s", "--short")
        col = get_opt(sub_args, "--color") or color_mode
        print_version(short, col)
        sys.exit(0)
    elif subcommand == "init":
        branch = get_opt(sub_args, "-b", "--branch")
        do_init(branch, cwd=cwd)
        sys.exit(0)
    elif subcommand == "series":
        branch = get_opt(sub_args, "-b", "--branch")
        all_flag = has_flag(sub_args, "-a", "--all")
        applied = has_flag(sub_args, "-A", "--applied")
        unapplied = has_flag(sub_args, "-U", "--unapplied")
        hidden = has_flag(sub_args, "-H", "--hidden")
        author = has_flag(sub_args, "--author")
        count = has_flag(sub_args, "-c", "--count")
        description = has_flag(sub_args, "-d", "--description")
        empty = has_flag(sub_args, "-e", "--empty")
        reverse = has_flag(sub_args, "--reverse", "-r")
        short_has=False
        short_val=None
        for i,arg in enumerate(sub_args):
            if arg in ("-s","--short"):
                short_has=True
                if i+1 < len(sub_args) and not sub_args[i+1].startswith("-"):
                    try:
                        short_val=int(sub_args[i+1])
                    except:
                        short_val=None
            elif arg.startswith("--short="):
                short_has=True
                try:
                    short_val=int(arg.split("=",1)[1])
                except:
                    short_val=None
            elif arg.startswith("-s") and len(arg)>2:
                short_has=True
                try:
                    short_val=int(arg[2:])
                except:
                    short_val=None
        short = short_val if short_has else None
        commit_id=None
        for i,arg in enumerate(sub_args):
            if arg in ("-i","--commit-id"):
                commit_id=(True,None)
                if i+1 < len(sub_args) and not sub_args[i+1].startswith("-"):
                    commit_id=(True,sub_args[i+1])
            elif arg.startswith("--commit-id="):
                commit_id=(True,arg.split("=",1)[1])
            elif arg.startswith("-i") and len(arg)>2:
                commit_id=(True,arg[2:])
        missing = get_opt(sub_args, "-m", "--missing")
        col = get_opt(sub_args, "--color") or color_mode
        pf=[]
        i=0
        while i < len(sub_args):
            a = sub_args[i]
            if a in ("-b","--branch","-m","--missing","-i","--commit-id","-s","--short"):
                i+=2
                continue
            if a.startswith("--branch=") or a.startswith("--missing=") or a.startswith("--commit-id=") or a.startswith("--short="):
                i+=1
                continue
            if a in ("-a","--all","-A","--applied","-U","--unapplied","-H","--hidden","--author","-c","--count","-d","--description","-e","--empty","--reverse","-r","-P","--no-prefix","-I","--indices","-O","--offsets"):
                i+=1
                continue
            if a.startswith("-"):
                i+=1
                continue
            pf.append(a)
            i+=1
        do_series(pf, branch, col, all_flag, short, applied, unapplied, hidden, missing, author, count, commit_id, description, empty, reverse, cwd=cwd)
        sys.exit(0)
    elif subcommand == "new":
        patchname_opt=None
        name_opt = get_opt(sub_args, "-n", "--name")
        message_opt = get_opt(sub_args, "-m", "--message")
        file_opt = get_opt(sub_args, "-f", "--file")
        refresh = has_flag(sub_args, "-r", "--refresh")
        index_flag = has_flag(sub_args, "-i", "--index")
        force = has_flag(sub_args, "-F", "--force")
        path_args=[]
        if "--" in sub_args:
            idx = sub_args.index("--")
            path_args = sub_args[idx+1:]
            sub_args = sub_args[:idx]
        positional=[]
        skip_next=False
        i=0
        while i < len(sub_args):
            a = sub_args[i]
            if skip_next:
                skip_next=False
                i+=1
                continue
            if a in ("-n","--name","-m","--message","-f","--file","--author","--authname","--authemail","--authdate","--save-template","-s","--signoff","--ack","--review"):
                skip_next=True
                i+=1
                continue
            if "=" in a and any(a.startswith(opt+"=") for opt in ("--name","--message","--file","--author","--authname","--authemail","--authdate","--save-template","--signoff","--ack","--review")):
                i+=1
                continue
            if a.startswith("-"):
                i+=1
                continue
            positional.append(a)
            i+=1
        if positional:
            patchname_opt = positional[0]
            if len(positional)>1:
                path_args = positional[1:] + path_args
        do_new(patchname_opt, path_args, name_opt, refresh, index_flag, force, message_opt, file_opt, cwd=cwd)
        sys.exit(0)
    elif subcommand == "refresh":
        message_opt = get_opt(sub_args, "-m", "--message")
        file_opt = get_opt(sub_args, "-f", "--file")
        index_flag = has_flag(sub_args, "-i", "--index")
        force = has_flag(sub_args, "-F", "--force")
        patch_opt = get_opt(sub_args, "-p", "--patch")
        path_args=[]
        skip_next=False
        i=0
        while i < len(sub_args):
            a = sub_args[i]
            if skip_next:
                skip_next=False
                i+=1
                continue
            if a in ("-m","--message","-f","--file","-p","--patch","-a","--annotate","--conflicts"):
                skip_next=True
                i+=1
                continue
            if "=" in a:
                if any(a.startswith(opt+"=") for opt in ("--message","--file","--patch","--annotate","--conflicts","--author","--authname","--authemail","--authdate","--save-template","--signoff","--ack","--review")):
                    i+=1
                    continue
            if a.startswith("-"):
                i+=1
                continue
            path_args.append(a)
            i+=1
        do_refresh(path_args, index_flag, force, patch_opt, message_opt, file_opt, cwd=cwd)
        sys.exit(0)
    elif subcommand == "pop":
        all_flag = has_flag(sub_args, "-a", "--all")
        number=None
        n_str = get_opt(sub_args, "-n", "--number")
