        spill = has_flag(sub_args, "-s", "--spill")
        keep = has_flag(sub_args, "-k", "--keep")
        patch_args=[]
        i=0
        skip_next=False
        while i < len(sub_args):
            a = sub_args[i]
            if skip_next:
                skip_next=False
                i+=1
                continue
            if a in ("-n","--number"):
                skip_next=True
                i+=1
                continue
            if a.startswith("--number="):
                i+=1
                continue
            if a in ("-a","--all","-s","--spill","-k","--keep"):
                i+=1
                continue
            if a.startswith("-"):
                i+=1
                continue
            patch_args.append(a)
            i+=1
        do_pop(patch_args, all_flag, number, spill, keep, cwd=cwd)
        sys.exit(0)
    elif subcommand == "push":
        all_flag = has_flag(sub_args, "-a", "--all")
        number=None
        n_str = get_opt(sub_args, "-n", "--number")
        if n_str:
            try:
                number=int(n_str)
            except:
                pass
        patch_args=[]
        i=0
        skip_next=False
        while i < len(sub_args):
            a = sub_args[i]
            if skip_next:
                skip_next=False
                i+=1
                continue
            if a in ("-n","--number","--conflicts"):
                skip_next=True
                i+=1
                continue
            if a.startswith("--number=") or a.startswith("--conflicts="):
