                continue
            if a in ("-a","--all","--reverse","--noapply","--set-tree","-k","--keep","-m","--merged","--committer-date-is-author-date"):
                i+=1
                continue
            if a.startswith("-"):
                i+=1
                continue
            patch_args.append(a)
            i+=1
        do_push(patch_args, all_flag, number, cwd=cwd)
        sys.exit(0)
    elif subcommand == "top":
        col = get_opt(sub_args, "--color") or color_mode
        do_top(col, cwd=cwd)
        sys.exit(0)
